#[test]
fn max_message_bytes_limits_bodies() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(attrs["Attributes"]["MaxMessageBytes"], 4);
    send(&mut h, "q", "abcd");
    // "é" is two bytes in UTF-8.
    send(&mut h, "q", "éé");
    for body in ["abcde", "ééa"] {
        let code = h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": body}));
        assert_eq!(code, "InvalidParameterValue");
    }
    // The rule comes before the standard-queue GroupId rule.
    let code = h.err(
        json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcde", "GroupId": "g"}),
    );
    assert_eq!(code, "InvalidParameterValue");
    // A failed send uses no message id.
    assert_eq!(send(&mut h, "q", "x")["MessageId"], "m-3");
}

#[test]
fn max_message_bytes_attribute_rules() {
    let mut h = Harness::new();
    let attrs = |v: Value| json!({"Command": "CreateQueue", "QueueName": "d", "Attributes": v});
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": 0}))), "InvalidParameterValue");
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": 1025}))), "InvalidParameterValue");
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": "9"}))), "InvalidParameterValue");
    h.ok(attrs(json!({})));
    let got = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "d"}));
    assert_eq!(got["Attributes"]["MaxMessageBytes"], 1024);
    // Part of CreateQueue rule 4.
    h.ok(attrs(json!({"MaxMessageBytes": 1024})));
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": 10}))), "QueueAlreadyExists");
}

#[test]
