    let mut h = Harness::new();
    let attrs = |v: Value| json!({"Command": "CreateQueue", "QueueName": "d", "Attributes": v});
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": 0}))), "InvalidParameterValue");
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": 1025}))), "InvalidParameterValue");
    assert_eq!(h.err(attrs(json!({"MaxMessageBytes": "9"}))), "InvalidParameterValue");
